<?php require_once __DIR__.'/includes/auth.php';require_login(['admin','hod']);$rows=db()->query("SELECT e.*,c.course_code FROM email_logs e LEFT JOIN result_records r ON r.id=e.result_id LEFT JOIN courses c ON c.id=r.course_id ORDER BY e.sent_at DESC LIMIT 200")->fetchAll();$pageTitle='Email Log | IFT';require __DIR__.'/includes/header.php';?><body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Email Log</span></div></div><a class="portal-back" href="<?=current_user()['role']==='hod'?'hod-dashboard.php':'admin-dashboard.php'?>">← Dashboard</a></header><main class="portal-main"><div class="page-title"><div><span class="kicker">NOTIFICATIONS</span><h1>Email Log</h1><p>Every attempted notification is recorded with delivery status.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Recipient</th><th>Course</th><th>Notification</th><th>Status</th><th>Error</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d M H:i',strtotime($r['sent_at'])))?></td><td><?=e($r['recipient'])?></td><td><?=e($r['course_code']??'—')?></td><td><?=e($r['event_name'])?></td><td><span class="table-status <?=strtolower($r['status'])==='sent'?'green':'orange'?>"><?=e($r['status'])?></span></td><td><?=e($r['error_message']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No email attempts yet.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
